class Builder:
    """Strategy design pattern to create proper Builder"""

    def __new__(cls: type, _type: str, _object: dict) -> "UserInterface":
        _type = _type.lower()
        if _type == "gui":
            return GuiBuilder(_object)
        if _type == "cli":
            return CliBuilder(_object)
        if _type == "robot":
            return RobotBuilder(_object)
        raise AttributeError(
            "Provided builder type ({}) is not supported. Please choose from following: {}".format(
                _type, ["gui", "cli", "robot"]
            )
        )


class UserInterface(metaclass=ABCMeta):
    """Abstract interface for Builders."""

    def __init__(self):
        """Basic initialization."""
        super().__init__()
        self.logger = get_net_logger(SERVER_HOST, LOGGER_PORT, "Builder")
        self.plugins = {}
        self._all_plugins = ALL_PLUGINS
        self._emss_config = {}

    @property
    def emss_config(self):
        """
        Property of emss configuration.
        Exmaple: {'emss_1': {'host': '10.0.1.1', 'id': 1}}

        :return: dict of emss configurations
        """
        if not self._emss_config:
            self._emss_config = self._create_emss_config()
        return self._emss_config

    @abstractmethod
    def _create_emss_config(self):
        pass

    def build(self) -> dict:
        """
        Builds dict of configuration for all selected plugins.

        :return: dict with plugins configuration
        """
        for plugin in self._get_activated_plugins():
            try:
                build_method = getattr(self, f"_build_{plugin}")
                build_method()
            except Exception as err:
                self.logger.exception(
                    f"Error: {err} during building plugin {plugin}",
                    exc_info=True,
                )
        self.logger.info(f"Discovered plugins: {list(self.plugins)}")
        self.logger.debug(f"Plugins detailed: {self.plugins}")
        self._send_stats()
        self.logger.debug("after send stats")
        return self.plugins

    @abstractmethod
    def _get_activated_plugins(self):
        pass

    @abstractmethod
    def _get_emil_stop_docker(self, vm_no: int) -> bool: ...

    @abstractmethod
    def _get_emil_messages(self, vm_no: int) -> tuple[list[str], list[str]]: ...

    @abstractmethod
    def _get_bts_ip(self, vm_no: int) -> str: ...

    @abstractmethod
    def _get_rat(self): ...

    @abstractmethod
    def _build_syslog(self):
        pass

    def _build_ims(self):
        """Build correct start request for ims plugin."""
        self.plugins["ims"] = {}

    def _build_scfc(self):
        """Build correct start request for scfc plugin."""
        self.plugins["scfc"] = {}

    def _build_snapshot(self):
        """Build correct start request for snapshot plugin."""
        self.plugins["snapshot"] = {}

    def _build_swconfig(self):
        """Build correct start request for swconfig plugin."""
        self.plugins["swconfig"] = {}

    @abstractmethod
    def _build_bip(self):
        pass

    def _build_emss(self):
        """Build correct start request for emss plugin."""
        self.plugins["emss"] = {"kwargs": {"emss_conf": self.emss_config}}

    @abstractmethod
    def _build_epc(self):
        pass

    def _build_emil(self):
        """Build correct start request for emil plugin."""
        rat = self._get_rat()
        data_per_vm = {}
        for vm_no in range(1, MAX_SUPPORTED_VMs + 1):
            stop_docker = self._get_emil_stop_docker(vm_no)
            bts_ip = self._get_bts_ip(vm_no)
            msg_filters, heavy_load_msg_filters = (",".join(msgs) for msgs in self._get_emil_messages(vm_no))
            data_per_vm[f"vm{vm_no}"] = {
                "stop_docker": stop_docker,
                "msgs": msg_filters,
                "heavy_load": heavy_load_msg_filters,
                "rat": rat,
                "bts_ip": bts_ip,
            }
            self.logger.debug(
                f"EMIL-{vm_no} plugin data: {msg_filters = }, {heavy_load_msg_filters = }, {rat = }, {stop_docker = }, {bts_ip = }"
            )
        self.plugins["emil"] = {"kwargs": data_per_vm}

    @abstractmethod
    def _build_final_report(self):
        pass

    @abstractmethod
    def _build_tti_trace(self):
        pass

    @abstractmethod
    def _build_ue_sim(self):
        pass

    @abstractmethod
    def _build_wireshark(self):
        pass

    def _build_alarms(self):
        """Build correct start request for alarms plugin."""
        self.plugins["alarms"] = {"kwargs": {"bts_info": self.emss_config}}

    def _send_stats(self):
        """Collect information from log collector and store in MongoDB."""
        if os.getenv("TA_LOGCOLLECTOR_DISABLE_STATS", "False").lower() == "true" or is_dry_run():
            self.logger.debug("Stats collection is disabled.")
            return
        from taf.ul.telemetry import telemetry_register

        tl = telemetry_register()
        with tl.trace("send_stats") as send_stats_trace:
            robot_file = get_robot_variable("SUITE SOURCE")
            if not robot_file:
                robot_file = "Unknown"
            try:
                tl_loc, tl_name = get_testline(self.logger)
            except AttributeError:
                tl_loc, tl_name = "Unknown", "Unknown"
            try:
                with open("/home/ute/testline_init_results/logs/INFO_log.txt") as f:
                    agent_log = f.read()
                tl_type = search(r"LABEL:\s?(.*)", agent_log)
                tl_type = tl_type.group(1)
            except Exception as exp:
                self.logger.debug(
                    msg=f"Can not find out TL type, exception: {str(exp)}",
                    exc_info=True,
                )
                tl_type = "Unknown"
            send_stats_trace.set_attributes(
                {
                    "version": __version__,
                    "builder": self.__class__.__name__,
                    "tl_type": tl_type,
                    "tl_name": tl_name,
                    "location": tl_loc,
                    "robot_file": split(robot_file)[-1],
                    "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                    "plugins": json.dumps({plugin: 1 for plugin in self.plugins}),
                }
            )
        with tl.trace("plugins_details") as plugins_trace:
            plugins_trace.set_attributes(
                {plugin: json.dumps(self.plugins[plugin], indent=4) for plugin in self.plugins}
            )


class CliBuilder(UserInterface):
    """Plugin builder for CLI Interface"""

    def __init__(self, config):
        """Basic initialization."""
        super().__init__()
        self.config = config

    def _get_emil_messages(self, vm_no: int) -> tuple[list[str], list[str]]:
        profiles = self.config["emil"].get(f"vm{vm_no}", {}).get("profiles", [])
        msg_filters = []
        heavy_load_msg_filters = []
        for profile in profiles:
            msg_filters.extend(PROFILES.get(profile, {}).get("Message filter", []))
            heavy_load_msg_filters.extend(PROFILES.get(profile, {}).get("Heavy Load Messages", []))
        msg_filters = merge_hex_lists(msg_filters)
        heavy_load_msg_filters = self._get_unique_heavy_load_msg_filters(heavy_load_msg_filters)
        return msg_filters, heavy_load_msg_filters

    @staticmethod
    def _get_unique_heavy_load_msg_filters(heavy_load_msg_filters):
        return list({msg.split(" #")[0] for msg in heavy_load_msg_filters})

    def _get_emil_stop_docker(self, vm_no: int) -> bool:
        return self.config["emil"].get(f"vm{vm_no}", {}).get("stop_docker", True)

    def _get_rat(self):
        # todo implement reading if it's gnb from TAF.TestLine
        cfg, _ = get_tl_cfg(self.logger)
        return RAT.LTE if is_4g(1, cfg) else RAT.NR

    def _get_bts_ip(self, vm_no: int) -> str:
        return self.config["emil"].get(f"vm{vm_no}", {}).get("bts_ip", "")

    def _get_activated_plugins(self):
        return (plugin for plugin in self.config if plugin != "main" and self.config[plugin]["active"])

    def _build_bip(self):
        """Build correct start request for bip plugin when running from Robot Framework test."""
        bip_conf = self.config["bip"]
        self.logger.debug(f"[BIP] config: {bip_conf}")
        self.plugins["bip"] = bip_conf

    def _build_emss(self):
        """Suppressing EMSS builder for Robot. EMSS will handle logs on it's own."""
        self.logger.debug("Suppressing emss for robot interface.")

    def _build_syslog(self):
        """Build correct start request for syslog plugin."""
        syslog_conf = {"compress": self.config["syslog"].pop("compress", True)}
        main_vm = {key for key in self.config["main"] if "vm" in key}
        syslog_vm = {key for key in self.config["syslog"] if "vm" in key}
        for vm, vm_dict in [(key, val) for key, val in self.config["syslog"].items() if key in main_vm & syslog_vm]:
            syslog_conf[vm] = {
                dev: vm_dict[ip] for dev, ip in {"enb": "enb_ip", "ue_sim": "ue_sim_ip"}.items() if vm_dict[dev]
            }
            for dev, ip_list in syslog_conf[vm].items():
                if dev == "enb" and not ip_list:
                    syslog_conf[vm][dev] = ["192.168.255.126"]
                if dev == "ue_sim" and not ip_list:
                    syslog_conf[vm][dev] = ["192.168.200.126"]
        self.plugins["syslog"] = {"kwargs": syslog_conf}

    def _build_tti_trace(self):
        """Build correct start request for tti_trace plugin when running from Robot Framework test."""
        tti_trace_conf = {key: val for key, val in self.config["tti_trace"].items() if key == "cells"}
        if not tti_trace_conf["cells"]:
            for vm_name in [vm for vm in self.config["main"] if vm.startswith("vm")]:
                self.logger.debug(f"[TTI] Will fetch cell-mapping for {vm_name}")
                cell_map = CellMapping(host=ENB_IPs[vm_name], logger=self.logger)().cell_mapping
                self.logger.debug(f"[TTI] {vm_name} Fetched cell mapping: {cell_map}")
                tti_trace_conf["cells"].update(
                    {int(vm_name[-1]): {int(cell_info["lnCel"]): "ULDL" for cell_info in cell_map}}
                )
        else:
            self.logger.debug("[TTI] Handle case when only eNBs are provided with known cells.")
            for enb, value in tti_trace_conf["cells"].items():
                if not value:
                    self.logger.debug("[TTI] Will fetch cell-mapping for {}".format(f"vm{enb}"))
                    cell_map = CellMapping(host=ENB_IPs[f"vm{enb}"], logger=self.logger)().cell_mapping
                    self.logger.debug("[TTI] {} Fetched cell mapping: {}".format(f"vm{enb}", cell_map))
                    tti_trace_conf["cells"].update({enb: {int(cell_info["lnCel"]): "ULDL" for cell_info in cell_map}})
        self.logger.debug(f"[TTI] config: {tti_trace_conf}")
        self.plugins["tti_trace"] = {"kwargs": tti_trace_conf}

    def _build_epc(self):
        """Build correct start request for epc plugin."""
        conf_data = {
            "egate_host": self.config["epc"]["egate_host"],
            "egate_port": self.config["epc"]["egate_port"],
            "egate_log_level": self.config["epc"]["egate_log_level"],
            "connect_on_start": True,
        }
        self.plugins["epc"] = {"kwargs": {"configuration": conf_data}}

    def _build_final_report(self):
        """Build correct start request for final_report plugin."""
        plugin_data = {name: value for name, value in self.config["final_report"].items() if value and name != "active"}
        self.plugins["final_report"] = {"kwargs": plugin_data}
        if self.config["final_report"]["bts_info"]:
            self.plugins["final_report"]["kwargs"]["bts_info"] = self.emss_config

    def _build_ue_sim(self):
        """Build correct start request for ue_sim plugin."""
        ue_sim = {
            simulator: self.config["ue_sim"][simulator]
            for simulator in ["iphy", "cus"]  # , 'airphone']
            if self.config["ue_sim"][simulator]["active"]
        }
        self.plugins["ue_sim"] = {"kwargs": ue_sim}

    def _build_wireshark(self):
        """Build correct start request for wireshark plugin."""
        ue_sims = []
        for simulator in ["iphy", "cus"]:  # , 'airphone']
            if self.config["ue_sim"][simulator]["active"]:
                ue_sims.append(simulator)
        protocols = {
            name: True for name in self.config["wireshark"] if self.config["wireshark"][name] and name != "active"
        }
        if any(protocols.values()):
            self.plugins["wireshark"] = {"kwargs": {"protocols": protocols, "ue_sims": ue_sims}}

    def _create_emss_config(self):
        """Build emss configuration to be used in different plugins based on emss in any way"""
        return {
            "ip": get_emss_ip(self.config["emss"]["ip"]),
            "bts_ids": [idx for idx in range(1, MAX_SUPPORTED_VMs + 1) if self.config["emss"][f"bts_{idx}"]],
        }


class RobotBuilder(CliBuilder):
    """Plugin builder for Robot Interface"""

    pass


class GuiBuilder(UserInterface):
    """Plugin builder for GUI interface"""

    def __init__(self, gui):
        """Basic initialization."""
        super().__init__()
        self.gui = gui

    def _get_emil_messages(self, vm_no: int) -> tuple[list[str], list[str]]:
        msg_filters = [
            msg[0]
            for msg in EMIL_MSG_FILTERS_REGEX.findall(getattr(self.gui, f"pte_emil_msg_filters_{vm_no}").toPlainText())
        ]
        heavy_load_msg_filters = [
            msg[0]
            for msg in EMIL_MSG_FILTERS_REGEX.findall(
                getattr(self.gui, f"pte_emil_heavy_load_msg_filters_{vm_no}").toPlainText()
            )
        ]
        return msg_filters, heavy_load_msg_filters

    def _get_emil_stop_docker(self, vm_no: int) -> bool:
        return getattr(self.gui, f"cb_emil_stop_container_{vm_no}").isChecked()

    def _get_rat(self):
        return RAT.LTE if is_4g(1, self.gui.taf_tl_config) else RAT.NR


    def _get_bts_ip(self, vm_no: int) -> str:
        return getattr(self.gui, f"le_emil_bts_ip_{vm_no}").text()

    def _get_activated_plugins(self):
        return (plugin for plugin in self._all_plugins if getattr(self.gui, f"cb_{plugin}").isChecked())

    def _build_bip(self):
        """Build correct start request for bip plugin."""
        self.plugins["bip"] = self.gui.build_bip()

    def _build_syslog(self):
        """Build correct start request for syslog plugin."""
        full_syslog = self.gui.build_syslog()
        syslog_conf = {"compress": full_syslog.pop("compress")}
        del full_syslog["active"]
        for vm, vm_dict in full_syslog.items():
            syslog_conf[vm] = {
                dev: vm_dict[ip] for dev, ip in {"enb": "enb_ip", "iphy": "iphy_ip"}.items() if vm_dict[dev]
            }
        for vm in full_syslog:
            if not getattr(self.gui, f"gb_syslog_{vm}").isEnabled():
                del syslog_conf[vm]
        self.plugins["syslog"] = {"kwargs": syslog_conf}

    def _build_epc(self):
        """Build correct start request for epc plugin."""
        epc_cfg = self.gui.build_epc()
        del epc_cfg["active"]
        epc_cfg["connect_on_start"] = True
        self.plugins["epc"] = {"kwargs": {"configuration": epc_cfg}}

    def _build_final_report(self):
        """Build correct start request for final_report plugin."""
        final_report_cfg = self.gui.build_final_report(only_active=True)
        if final_report_cfg.get("ue_sim_sw", False):
            final_report_cfg["ue_sim_sw"] = {
                sim: sim_exists for sim, sim_exists in check_tl_config_for_ue_sim(self.gui.taf_tl_config) if sim_exists
            }
        if self.gui.cb_report_bts_info.isChecked():
            final_report_cfg["bts_info"] = self.emss_config
        del final_report_cfg["active"]
        self.plugins["final_report"] = {"kwargs": final_report_cfg}

    def _build_tti_trace(self):
        """Build correct start request for tti_trace plugin."""
        tti_per_vm_conf = {}
        for vm_host in self.gui.vm_hosts:
            vm_id = int(vm_host.strip("vm"))
            conf = self.gui.build_tti_trace(vm_id)
            del conf["active"]
            tti_per_vm_conf[f"vm{vm_id}"] = conf
        self.plugins["tti_trace"] = {"kwargs": tti_per_vm_conf}

    def _build_ue_sim(self):
        """Build correct start request for ue_sim plugin."""
        ue_sim = self.gui.build_ue_sim()
        del ue_sim["active"]
        self.plugins["ue_sim"] = {"kwargs": ue_sim}

    def _build_wireshark(self):
        """Build correct start request for wireshark plugin."""
        ue_sims = [sim for sim, active in self.gui.simulators_state.items() if active is True]
        protocols = {
            name: True for name in wireshark_protocols if getattr(self.gui, f"cb_wireshark_{name}").isChecked()
        }
        if any(protocols.values()):
            self.plugins["wireshark"] = {"kwargs": {"protocols": protocols, "ue_sims": ue_sims}}

    def _create_emss_config(self):
        return {
            "ip": self.gui.le_emss_ip.text(),
            "bts_ids": [
                idx for idx in range(1, MAX_SUPPORTED_VMs + 1) if getattr(self.gui, f"cb_emss_bts_vm{idx}").isChecked()
            ],
        }
